+    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
+    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;
+
+    private string? ErrorMessage;
+    private bool IsValidating;
+
+    private async Task UpdateField(PersonalInfo updated)
+    {
+        await OnChanged.InvokeAsync(updated);
+    }
+
+    private async Task HandleNext()
+    {
+        ErrorMessage = null;
+
+        if (string.IsNullOrWhiteSpace(Personal.FullName))
+        {
+            ErrorMessage = "Full name is required.";
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(Personal.Email))
+        {
+            ErrorMessage = "Email is required.";
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(Personal.Phone))
+        {
+            ErrorMessage = "Phone is required.";
+            return;
+        }
+
+        IsValidating = true;
+        var emailValid = await ValidateEmail(Personal.Email);
+        IsValidating = false;
+
+        if (!emailValid)
+        {
+            ErrorMessage = "Please enter a valid email address.";
+            return;
+        }
+
+        await OnNext.InvokeAsync();
+    }
