@page "/apply"
@using sv_b4a9f39c77aa492b949391e6a1db9193.Models
@using sv_b4a9f39c77aa492b949391e6a1db9193.Services
@namespace sv_b4a9f39c77aa492b949391e6a1db9193.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form-container">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep"
                   CompletedSteps="@_completedSteps"
                   OnStepSelected="GoToStep" />

    <div class="mt-4">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep Personal="@_personal"
                                  OnChanged="p => _personal = p"
                                  OnNext="NextStep"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync" />
                break;
            case 1:
                <WorkHistoryStep Entries="@_workEntries"
                                 OnChanged="entries => _workEntries = entries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="@_references"
                                OnChanged="refs => _references = refs"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 OnChanged="cl => _coverLetter = cl"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep Personal="@_personal"
                            WorkEntries="@_workEntries"
                            References="@_references"
                            CoverLetter="@_coverLetter"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep"
                            SubmitApplication="SubmitAsync" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep = 0;
    private HashSet<int> _completedSteps = new();

    private PersonalInfo _personal = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> _workEntries = new()
    {
        new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty)
    };
    private List<Reference> _references = new()
    {
        new Reference(string.Empty, string.Empty, string.Empty, string.Empty),
        new Reference(string.Empty, string.Empty, string.Empty, string.Empty)
    };
    private string _coverLetter = string.Empty;

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            _personal,
            new WorkHistory(_workEntries),
            _references,
            _coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-form-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 1.5rem;
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    padding: 1rem 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    cursor: default;
    min-width: 80px;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
}

.step-item.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

.step-item.dimmed .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-item.dimmed .step-label {
    opacity: 0.5;
}

.step-check {
    font-size: 1rem;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.25rem;
    margin-bottom: 1.5rem;
    max-width: 60px;
}

.step-connector.completed {
    background: #198754;
}

.step-content {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
    background: #fff;
}

.work-entry-form {
    padding: 1rem;
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section {
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    padding: 1rem;
}

