toolArgs.file_text:
@page "/apply"
@using sv_b4a9f39c77aa492b949391e6a1db9193.Models
@using sv_b4a9f39c77aa492b949391e6a1db9193.Services
@namespace sv_b4a9f39c77aa492b949391e6a1db9193.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form-container">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep"
                   CompletedSteps="@_completedSteps"
                   OnStepSelected="GoToStep" />

    <div class="mt-4">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep Personal="@_personal"
                                  OnChanged="p => _personal = p"
                                  OnNext="NextStep"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync" />
                break;
            case 1:
                <WorkHistoryStep Entries="@_workEntries"
                                 OnChanged="entries => _workEntries = entries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="@_references"
                                OnChanged="refs => _references = refs"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 OnChanged="cl => _coverLetter = cl"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep Personal="@_personal"
                            WorkEntries="@_workEntries"
                            References="@_references"
                            CoverLetter="@_coverLetter"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep"
                            SubmitApplication="SubmitAsync" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep = 0;
    private HashSet<int> _completedSteps = new();

    private PersonalInfo _personal = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> _workEntries = new()
    {
        new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty)
    };
    private List<Reference> _references = new()
    {
        new Reference(string.Empty, string.Empty, string.Empty, string.Empty),
        new Reference(string.Empty, string.Empty, string.Empty, string.Empty)
    };
    private string _coverLetter = string.Empty;

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            _personal,
            new WorkHistory(_workEntries),
            _references,
            _coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

